<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue';import {admin,date,money,mutationKey,safeUrl} from '../../../shared/api';import type {Page,AfterSale} from '../../../shared/types';import type {AdminAfterSale} from '../../../shared/adminTypes';import {useLoad} from '../../../shared/useLoad';import {ElMessage} from 'element-plus'
const result=ref<Page<AfterSale>>(),detail=ref<AdminAfterSale>(),open=ref(false),status=ref(''),review=reactive({reason:'',amount:0,conditionNotes:'',received:false}),key=mutationKey(),{loading,error,run}=useLoad();const labels:Record<string,string>={pending_review:'待审核',rejected:'已驳回',awaiting_return:'待退回',refunding:'退款中',resolved:'已完成',awaiting_exchange:'待换宠'}
const pageNumber=ref(1)
const load=()=>run(async()=>{result.value=await admin('GET','/admin/after-sales',undefined,{status:status.value,page:pageNumber.value,pageSize:20})})
const view=(id:string)=>run(async()=>{detail.value=await admin('GET',`/admin/after-sales/${id}`);Object.assign(review,{reason:'',amount:0,conditionNotes:'',received:false});open.value=true})
async function decide(decision:string){await run(async()=>{const d=detail.value!;const body={version:d.version,decision,reason:review.reason,...(decision==='approve'?{resolution:d.requestedResolution,...(d.requestedResolution==='treatment_share'?{approvedAmount:Math.round(review.amount*100)}:{})}:{})};const path=`/admin/after-sales/${d.id}/review`;await admin('POST',path,body,undefined,key(path,body));detail.value=await admin('GET',`/admin/after-sales/${detail.value!.id}`);ElMessage.success('审核结果已保存');result.value=await admin('GET','/admin/after-sales',undefined,{status:status.value,page:pageNumber.value,pageSize:20})})}
const receive=()=>run(async()=>{const path=`/admin/after-sales/${detail.value!.id}/returns`,body={version:detail.value!.version,received:true,conditionNotes:review.conditionNotes};await admin('POST',path,body,undefined,key(path,body));detail.value=await admin('GET',`/admin/after-sales/${detail.value!.id}`);ElMessage.success('退回记录已保存');result.value=await admin('GET','/admin/after-sales',undefined,{page:pageNumber.value,pageSize:20})})
const file=async(id:string)=>{await run(async()=>{const data=await admin<{url:string}>('GET',`/files/${id}/access-url`);window.open(safeUrl(data.url),'_blank','noopener,noreferrer')})}
onMounted(load)
</script>
<template><p class="eyebrow">AFTER-SALES</p><h2>材料、处理与结果，都有记录。</h2><div class="toolbar"><el-select v-model="status" placeholder="全部售后" clearable @change="load"><el-option v-for="(label,value) in labels" :key="value" :label="label" :value="value"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="table-panel"><el-table :data="result?.items||[]" v-loading="loading"><el-table-column prop="id" label="售后编号" min-width="200"/><el-table-column prop="orderId" label="订单编号" min-width="170"/><el-table-column label="诉求" min-width="120"><template #default="{row}">{{row.requestedResolution==='full_refund'?'全额退款':row.requestedResolution==='exchange'?'换宠':'治疗费分担'}}</template></el-table-column><el-table-column label="状态" min-width="120"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="view(row.id)">查看材料</el-button></template></el-table-column></el-table><el-pagination v-if="result" v-model:current-page="pageNumber" :page-size="20" :total="result.total" layout="prev,pager,next" @current-change="load"/></div><el-drawer v-model="open" title="售后审核与处理" size="600px"><template v-if="detail"><el-tag>{{labels[detail.status]}}</el-tag><h3 style="margin-top:20px">{{detail.order.product.name}} · {{money(detail.order.amount)}}</h3><p>{{detail.reason}}</p><p class="small">申请时间 {{date(detail.createdAt)}}</p><div class="actions"><el-button v-for="(id,index) in detail.diagnosisFileIds" :key="id" @click="file(id)">查看诊断报告 {{index+1}}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div v-if="detail.status==='pending_review'" class="stack" style="margin-top:24px"><el-input v-model="review.reason" type="textarea" :rows="4" placeholder="请记录责任认定依据与处理说明"/><label v-if="detail.requestedResolution==='treatment_share'">批准金额（元）<el-input-number v-model="review.amount" :min="0.01" :max="(detail.requestedAmount||0)/100" :precision="2"/></label><div class="actions"><el-button type="primary" :disabled="!review.reason.trim()" :loading="loading" @click="decide('approve')">通过申请</el-button><el-button :disabled="!review.reason.trim()" :loading="loading" @click="decide('reject')">驳回并说明原因</el-button></div></div><div v-if="detail.status==='awaiting_return'" class="stack" style="margin-top:24px"><el-input v-model="review.conditionNotes" type="textarea" placeholder="记录实际退回个体与健康观察"/><el-checkbox v-model="review.received">已现场收到原订单对应宠物</el-checkbox><el-button type="primary" :disabled="!review.received||!review.conditionNotes.trim()" :loading="loading" @click="receive">确认退回并继续处理</el-button></div><p v-if="detail.reviewReason" style="margin-top:24px">审核意见：{{detail.reviewReason}}</p><el-timeline style="margin-top:32px"><el-timeline-item v-for="(item,index) in detail.timeline" :key="index" :timestamp="date(item.occurredAt)">{{item.label}}<p>{{item.note}}</p></el-timeline-item></el-timeline><div class="status-note">健康责任由店主审核。退回宠物先下架，退款完成也不会自动重新上架。</div></template></el-drawer></template>
